def solve(nums):
    # Skeleton for: Palindrome Partitioning - II|(DP-53)
    memo = {}
    def dp(i):
        if i in memo:
            return memo[i]
        if i >= len(nums):
            return 0  # adapt base
        # adapt transition
        memo[i] = max(dp(i + 1), nums[i] + dp(i + 2))
        return memo[i]
    return dp(0)

def solve_bottom_up(nums):
    n = len(nums)
    if n == 0:
        return 0
    dp = [0] * (n + 1)
    dp[1] = nums[0]
    for i in range(2, n + 1):
        dp[i] = max(dp[i - 1], dp[i - 2] + nums[i - 1])
    return dp[n]
